SELECT count(*) AS filas_web FROM tmp_csv_compras_web;
SELECT count(*) AS filas, count(DISTINCT id_compra) AS ids_distintos, count_if(NOT regexp_like(fecha, '^\d{4}-\d{2}-\d{2}$')) AS fecha_mal_formato, count_if(anio <> substr(fecha, 1, 4) OR mes <> substr(fecha, 6, 2)) AS particion_inconsistente, count_if(try_cast(cantidad AS double) IS NULL OR try_cast(precio_unitario AS double) IS NULL) AS importe_invalido, count_if(NULLIF(trim(lead_time_dias), '') IS NOT NULL AND try_cast(trim(lead_time_dias) AS integer) IS NULL) AS lead_time_invalido, count_if(NULLIF(trim(lead_time_dias), '') IS NULL) AS lead_time_vacio FROM tmp_v_compras;
SELECT count(*) AS filas, count_if(p.proveedor_id IS NULL) AS sin_proveedor, count_if(pr.producto_id IS NULL) AS sin_producto, count_if(c.categoria_id IS NULL) AS sin_categoria, count_if(u.unidad_organizacional_id IS NULL) AS sin_unidad FROM tmp_v_compras v LEFT JOIN dim_proveedor p ON v.proveedor_id = p.proveedor_id LEFT JOIN dim_producto pr ON v.producto_id = pr.producto_id LEFT JOIN dim_categoria c ON v.categoria_id = c.categoria_id LEFT JOIN dim_unidad_organizacional u ON v.unidad_organizacional_id = u.unidad_organizacional_id;
SELECT anio, mes, count(*) AS compras FROM tmp_v_compras GROUP BY anio, mes ORDER BY anio, mes;
SELECT count(*) AS dias, min(CAST(d AS date)) AS desde, max(CAST(d AS date)) AS hasta FROM (SELECT min(date_parse(fecha_id, '%Y%m%d')) AS desde FROM hechos_compras) h CROSS JOIN UNNEST(sequence(h.desde, CAST(CAST(current_timestamp AT TIME ZONE 'America/Guatemala' AS date) AS timestamp), INTERVAL '1' DAY)) AS t(d);
